conic-border-spin.code:
@property --ak-angle { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
.ak-conic {
  position: relative; border-radius: 1rem; padding: 1.5rem 2rem;
  background: #0D0D12; color: #F4F2EC; isolation: isolate;
}
.ak-conic::before {
  content: ""; position: absolute; inset: -1.5px; z-index: -1; border-radius: inherit;
  background: conic-gradient(from var(--ak-angle), #FF3D00, #E5A93C, #00F0FF, #FF3D00);
  animation: ak-spin 3.2s linear infinite;
}
@keyframes ak-spin { to { --ak-angle: 360deg; } }
@media (prefers-reduced-motion: reduce) { .ak-conic::before { animation: none; } }
/* Fallback for browsers without @property: static 1px var(--line-strong) border + glow */
@supports not (background: conic-gradient(from 0deg, red, blue)) {
  .ak-conic::before { background: none; border: 1px solid rgba(244,242,236,0.24); }
}

glass-hairline-panel.code:
.ak-glass {
  position: relative;
  background: rgba(13, 13, 18, 0.62);
  backdrop-filter: blur(16px) saturate(0.9);
  -webkit-backdrop-filter: blur(16px) saturate(0.9);
  border: 1px solid rgba(244, 242, 236, 0.10);
  border-radius: 9999px;
  box-shadow: inset 0 1px 0 rgba(244, 242, 236, 0.08), 0 18px 50px -18px rgba(0, 0, 0, 0.6);
}
.ak-glass::before {
  content: ""; position: absolute; top: 0; left: 12%; right: 12%; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(244, 242, 236, 0.4), transparent);
}
